  "스토아 철학": "스토아 철학, 에피쿠로스 철학, 간다라 불교 미술(불상의 탄생) 등 세계시민주의(Cosmopolitanism) 문화를 촉발했습니다.",
  "아우프헤벤": "아우프헤벤은 모순을 단순히 부정하여 버리는 것이 아니라, 이전 단계의 가치를 보존(preserving)하면서 더 높은 수준으로 승화(elevating)시키는 이중적 의미를 갖습니다.",
  "베르트": "정지 문제의 결정 불가능성은 힐베르트의 결정문제(Entscheidungsproblem)를 부정적으로 해결하며 계산 가능성 이론의 초석이 되었습니다.",
  "방법적 회의": "데카르트는 모든 감각과 인식을 철저히 의심하는 방법적 회의 끝에, \"의심하고 있는 나 자신의 사유 행위만큼은 결코 의심할 수 없는 제1의 확실한 진리\"임을 발견했습니다.",
  "신즉자연": "스피노자는 신과 자연이 둘이 아니라 하나(신즉자연)이며, 세상의 모든 사건은 신의 본성에서 필연적으로 도출되므로 이를 '영원의 상 아래서' 지적으로 직관하고 인식할 때 진정한 자유와 지복(Beatitudo)에 이른다고 가르쳤습니다.",
  "화성기위": "화성기위은(는) 철학 & 사상에서 독자적인 개념적 정의와 학술적 적용 범주를 지니는 전문 학술 개념입니다.",
