  "로버즈 케이브 실험": "로버즈 케이브 실험은(는) 인간의 심리적 기제나 물리적 가설의 진위를 검증하기 위해 엄밀한 통제 하에서 실시된 학술 실험입니다.",
  "보보 인형 실험": "보보 인형 실험은(는) 인간의 심리적 기제나 물리적 가설의 진위를 검증하기 위해 엄밀한 통제 하에서 실시된 학술 실험입니다.",
  "시상": "볼츠만은 엔트로피를 미시상태의 수 W와 연결하여 S = k ln W라는 통계역학적 공식으로 정의했습니다.",
  "뇌량": "뇌량은(는) 심리학 & 인지과학에서 독자적인 개념적 정의와 학술적 적용 범주를 지니는 전문 학술 개념입니다.",
  "뇌하수체": "뇌하수체은(는) 심리학 & 인지과학에서 독자적인 개념적 정의와 학술적 적용 범주를 지니는 전문 학술 개념입니다.",
  "엔도르핀": "뇌에서 기대감(Expectation)에 의해 실제 천연 진통 물질인 엔도르핀과 도파민이 분비되어 통증이 줄어들고 면역 반응이 활성화됩니다.",
  "노시보 효과": "반대로 부작용이 없을 약인데도 부작용이 생길 것이라는 불안한 암시 때문에 실제로 부작용과 통증을 겪는 현상을 '노시보 효과(Nocebo Effect)'라고 부릅니다.",
  "헤일로 효과": "헤일로 효과은(는) 심리학 & 인지과학에서 특정 조건이나 작용에 의해 일관되게 관측되는 독자적인 물리적·인지적 반응 현상입니다.",
  "악마 효과": "반대로 단 하나의 부정적인 특성 때문에 그 사람의 다른 모든 장점까지 깎아내려 나쁘게 보는 것을 '악마 효과(Horn Effect)'라고 합니다.",
  "최신 효과": "단, 시간이 오래 지난 후에는 가장 마지막에 들은 정보가 더 잘 기억되는 최신 효과(Recency Effect)가 우세해집니다.",
  "후두엽": "양측 후두엽 시각피질이 광범위하게 파괴되었으나 전두엽의 모니터링 체계마저 손상되어 실명 상태 자체를 자각하지 못하고 뇌가 기억으로 가짜 시각을 작화합니다.",
  "두정엽": "의식적 시각 경로(망막-외측슬상핵-V1)가 끊어졌으나 의식에 도달하지 않는 원시적 진화 경로(망막-상구-시상침-편도체/두정엽)가 살아있기 때문입니다.",
