  "맥락 효과": "맥락 효과은(는) 심리학 & 인지과학에서 특정 조건이나 작용에 의해 일관되게 관측되는 독자적인 물리적·인지적 반응 현상입니다.",
  "시스템 2": "인간은 에너지 소모를 줄이기 위해 일상 결정의 대부분을 빠르고 어림짐작에 의존하는 시스템 1(휴리스틱)으로 처리하며, 깊은 주의 집중과 통계적 계산이 요구될 때만 시스템 2를 활성화합니다.",
